# -*- coding: utf-8 -*-
exec(open('lib7.py',encoding='utf-8').read())
c='p7';B='SQL 3A'
DB='thuexe'
def Q(tag,title,q,desc,note,db=DB,fs=22,ofs=22,ch='Ý chính'):
    o=SQLRUN(DBSETUP(db),q)
    return S2(c,B+' · '+tag,title,card(ch,P(*desc.split('<br>')))+CODE(PRETTY(q),fs),RES(OUT(o,ofs),'Kết quả chạy SQL')+(KEY(note) if note else ''))
S=[]
S.append(TITLE('TIN HỌC · SQL 3A','TRUY VẤN DỮ LIỆU<br>VỚI SQL','SELECT, WHERE, ORDER BY, LIMIT, DISTINCT, LIKE, IN, BETWEEN, IS NULL và các hàm tổng hợp COUNT, SUM, AVG, MIN, MAX, trên chính CSDL thuexe dùng trong đề.',['SELECT','WHERE','ORDER BY','COUNT','SUM']))
S.append(goals(c,B,['Viết truy vấn <b>SELECT … FROM … WHERE … ORDER BY</b>.','Dùng <b>DISTINCT, LIKE, IN, BETWEEN, LIMIT</b>.','Dùng hàm tổng hợp <b>COUNT, SUM, AVG, MIN, MAX</b> và <b>COUNT(DISTINCT …)</b>.','Phân biệt <b>COUNT(*)</b> và <b>COUNT(cột)</b>; biết tính <b>NULL</b>.','Đọc đúng đề kiểu HSG: “từ … trở lên”, “khác nhau”, “của loại …”.'],['SELECT, WHERE','Toán tử điều kiện','ORDER BY, LIMIT','Hàm tổng hợp','Tự kiểm tra']))
S.append(S2(c,B+' · 0','CSDL thuexe: ba bảng dùng xuyên suốt',card('Quan hệ giữa các bảng',P('<b>KhachThue</b>(MaKT, TenKT, SDT): khách thuê.','<b>PhuongTien</b>(MaPT, LoaiPT): phương tiện (xe điện, xe đạp, xe máy).','<b>LuotThue</b>(MaLuot, MaKT, MaPT, Tram, SoGio, NgayThue): mỗi lượt thuê; <b>MaKT, MaPT là khoá ngoài</b> tới hai bảng kia.')),TBL(DB,'LuotThue',16,limit=12)))
S.append(Q('1','SELECT: chọn cột','SELECT MaKT, SoGio FROM LuotThue','<b>SELECT</b> liệt kê các cột cần lấy; <b>FROM</b> chỉ bảng.<br><b>SELECT *</b> lấy mọi cột.','Kết quả luôn là một <b>bảng</b>: 2 cột, 12 dòng.',ofs=17,ch='Cú pháp cơ bản'))
S.append(Q('1','Cột tính toán và bí danh AS','SELECT MaLuot, SoGio, SoGio*15000 AS TienThue FROM LuotThue WHERE MaLuot<=4','Có thể viết <b>biểu thức</b> trong SELECT; <b>AS</b> đặt tên cho cột kết quả.','<b>AS</b> chỉ đổi tên cột trong kết quả, không đổi dữ liệu gốc.',ch='Biểu thức và AS'))
S.append(Q('1','DISTINCT: loại dòng trùng','SELECT DISTINCT MaKT FROM LuotThue','<b>DISTINCT</b> chỉ giữ <b>một</b> dòng cho các dòng giống hệt nhau.<br>12 lượt thuê nhưng chỉ có <b>5 khách khác nhau</b>.','DISTINCT áp dụng cho <b>cả tổ hợp cột</b> sau nó.',ch='Loại trùng'))
S.append(Q('2','WHERE: lọc dòng theo điều kiện',"SELECT MaLuot, MaKT, SoGio FROM LuotThue WHERE SoGio >= 4 AND Tram = 'DN01'",'<b>WHERE</b> giữ lại những <b>dòng</b> thoả điều kiện; ghép bằng <b>AND, OR, NOT</b>.<br>Xâu viết trong <b>nháy đơn</b>.','“<b>từ 4 giờ trở lên</b>” nghĩa là <b>&gt;=</b>, không phải &gt;.',fs=20,ch='Lọc dòng'))
S.append(TB(c,B+' · 2','Toán tử dùng trong điều kiện',['Toán tử','Ý nghĩa','Ví dụ'],[['<code>= &lt;&gt; &lt; &gt; &lt;= &gt;=</code>','so sánh (khác: <code>&lt;&gt;</code> hoặc <code>!=</code>)','<code>SoGio &lt;&gt; 3</code>'],['<code>AND / OR / NOT</code>','và / hoặc / phủ định','<code>Tram=\'DN01\' OR Tram=\'DN02\'</code>'],['<code>IN (…)</code>','thuộc một tập giá trị','<code>Tram IN (\'DN01\',\'DN02\')</code>'],['<code>BETWEEN a AND b</code>','trong đoạn [a, b], <b>gồm hai đầu</b>','<code>SoGio BETWEEN 3 AND 5</code>'],['<code>LIKE</code>','khớp mẫu: <b>%</b> nhiều kí tự, <b>_</b> một kí tự','<code>TenKT LIKE \'H%\'</code>'],['<code>IS NULL / IS NOT NULL</code>','kiểm tra giá trị rỗng (<b>không dùng = NULL</b>)','<code>SDT IS NULL</code>']],note=KEY('Tìm theo năm với ngày dạng chữ: <code>NgayThue LIKE \'2026%\'</code> hoặc <code>BETWEEN \'2026-01-01\' AND \'2026-12-31\'</code>.')))
S.append(Q('2','AND, OR và dấu ngoặc',"SELECT MaLuot, Tram, SoGio, NgayThue FROM LuotThue WHERE SoGio >= 4 AND (Tram = 'DN01' OR Tram = 'DN02') AND NgayThue LIKE '2026%'",'Đề: “số giờ từ 4 trở lên, tại trạm DN01 <b>hoặc</b> DN02, trong năm 2026”.<br>Có <b>OR</b> trộn với <b>AND</b> thì <b>phải đặt ngoặc</b>.','<b>AND</b> được tính trước <b>OR</b>; thiếu ngoặc cho kết quả sai.',fs=18,ch='Ngoặc quyết định'))
S.append(Q('2','Thiếu ngoặc: kết quả sai',"SELECT MaLuot, Tram, SoGio FROM LuotThue WHERE SoGio >= 4 AND Tram = 'DN01' OR Tram = 'DN02'",'Câu trên bị hiểu là: (SoGio≥4 <b>và</b> DN01) <b>hoặc</b> (DN02).<br>Lượt thuê DN02 <b>mọi số giờ</b> đều lọt vào.','So sánh với slide trước: kết quả khác vì thiếu ngoặc.',fs=19,ch='Cái bẫy'))
S.append(Q('2','LIKE và IN',"SELECT TenKT, SDT FROM KhachThue WHERE TenKT LIKE '%ng' OR MaKT IN ('K001','K006')",'<b>LIKE \'%ng\'</b>: kết thúc bằng “ng”; <b>%</b> thay cho nhiều kí tự bất kì, <b>_</b> thay đúng một kí tự.','IN gọn hơn nhiều OR: <code>MaKT IN (\'K001\',\'K006\')</code>.',fs=20,ch='Khớp mẫu và tập giá trị'))
S.append(Q('3','ORDER BY và LIMIT','SELECT MaLuot, MaKT, SoGio FROM LuotThue ORDER BY SoGio DESC, MaLuot LIMIT 3','<b>ORDER BY</b> cột [ASC|DESC]: mặc định <b>tăng dần</b>; <b>DESC</b> giảm dần; sắp theo nhiều cột, cách nhau dấu phẩy.<br><b>LIMIT n</b> lấy n dòng đầu.','ORDER BY luôn viết <b>sau cùng</b> (trước LIMIT).',fs=20,ch='Sắp xếp'))
S.append(Q('3','Thứ tự viết một câu truy vấn',"SELECT MaKT, SoGio FROM LuotThue WHERE Tram='DN01' ORDER BY SoGio DESC",'Thứ tự viết: <b>SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT</b>.','Ghi nhớ thứ tự này để không viết nhầm vị trí mệnh đề.',fs=20,ch='Khung truy vấn'))
S.append(Q('4','Hàm tổng hợp: COUNT, SUM, AVG, MIN, MAX','SELECT COUNT(*) AS SoLuot, SUM(SoGio) AS TongGio, AVG(SoGio) AS TB, MIN(SoGio) AS Min, MAX(SoGio) AS Max FROM LuotThue','Hàm tổng hợp <b>gộp nhiều dòng thành một giá trị</b>: đếm, cộng, trung bình, nhỏ nhất, lớn nhất.<br>Không có GROUP BY: cả bảng thành <b>một dòng</b>.','Kết quả chỉ <b>1 dòng</b> dù bảng có 12 dòng.',fs=17,ch='Gộp thành một số'))
S.append(Q('4','Tổng giờ của một khách','SELECT SUM(SoGio) AS TongGio FROM LuotThue WHERE MaKT = \'K001\'','<b>WHERE lọc trước</b>, rồi <b>SUM cộng</b> trên các dòng còn lại.<br>Không cần GROUP BY khi chỉ cần <b>một khách</b>.','Khách K001 có 4 lượt: 3 + 3 + 4 + 1 = 11 giờ.',fs=20,ch='Lọc rồi tính'))
S.append(Q('4','Tổng giờ thuê xe điện (cần liên kết bảng)',"SELECT SUM(l.SoGio) AS TongGioXeDien FROM LuotThue l JOIN PhuongTien p ON l.MaPT = p.MaPT WHERE p.LoaiPT = 'Xe điện'",'Loại phương tiện nằm ở bảng <b>PhuongTien</b>, giờ ở bảng <b>LuotThue</b> → cần <b>JOIN</b> (sẽ học kĩ ở bài sau).<br><b>l</b> và <b>p</b> là bí danh bảng.','Đề hỏi “của loại Xe điện” → luôn nghĩ tới nối bảng.',fs=17,ch='Hai bảng'))
S.append(S2(c,B+' · 4','COUNT(*), COUNT(cột), COUNT(DISTINCT cột)',card('Ba cách đếm khác nhau',P('<b>COUNT(*)</b>: đếm <b>số dòng</b>.','<b>COUNT(cột)</b>: đếm dòng mà cột <b>khác NULL</b>.','<b>COUNT(DISTINCT cột)</b>: đếm số giá trị <b>khác nhau</b>.','Đề “<b>có bao nhiêu khách KHÁC NHAU</b> đã từng thuê” → <b>COUNT(DISTINCT MaKT)</b>.')),RES(OUT(RESQ(DB,'SELECT COUNT(*) AS dong, COUNT(MaKT) AS cot, COUNT(DISTINCT MaKT) AS khach_khac_nhau FROM LuotThue'),24),'Kết quả chạy SQL')+CODE('SELECT COUNT(*), COUNT(MaKT),\n       COUNT(DISTINCT MaKT)\nFROM LuotThue',20)+KEY('Một khách thuê nhiều lần: <b>COUNT(MaKT) = 12</b> nhưng <b>COUNT(DISTINCT MaKT) = 5</b>.')))
S.append(S2(c,B+' · 4','Hàm tổng hợp và NULL',card('Quy tắc về NULL',P('<b>SUM, AVG, MIN, MAX, COUNT(cột)</b> <b>bỏ qua NULL</b>.','<b>COUNT(*)</b> đếm cả dòng có NULL.','<b>AVG</b> chia cho số giá trị <b>khác NULL</b>, không chia cho số dòng.')),RES(OUT(SQLRUN("CREATE TABLE t(x INT); INSERT INTO t VALUES(2),(4),(NULL);","SELECT COUNT(*) AS dem_dong, COUNT(x) AS dem_x, SUM(x) AS tong, AVG(x) AS tb FROM t"),24),'Bảng t có 3 dòng: 2, 4, NULL')+KEY('AVG = (2+4)/<b>2</b> = 3, không phải /3.')))
S.append(SELF(c,B+' · 5','Tự kiểm tra 1: từ … trở lên','Viết điều kiện cho “lượt thuê có số giờ từ 4 trở lên”. Có bao nhiêu lượt thoả?',"SELECT COUNT(*) FROM LuotThue\nWHERE SoGio >= 4;",P('“Từ 4 trở lên” → <b>SoGio &gt;= 4</b> (gồm cả 4).','Kết quả chạy thật: <b>%s</b> lượt.'%SQL1('SELECT COUNT(*) FROM LuotThue WHERE SoGio>=4',DBSETUP(DB)),'Nếu viết &gt; 4 sẽ thiếu các lượt đúng 4 giờ.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra 2: khách khác nhau','Có bao nhiêu khách KHÁC NHAU đã từng thuê phương tiện?','SELECT COUNT(DISTINCT MaKT)\nFROM LuotThue;',P('Cần đếm <b>khách khác nhau</b> → <b>COUNT(DISTINCT MaKT)</b>.','Chạy thật: <b>%s</b>.'%SQL1('SELECT COUNT(DISTINCT MaKT) FROM LuotThue',DBSETUP(DB)),'COUNT(MaKT) cho <b>%s</b>, đếm trùng.'%SQL1('SELECT COUNT(MaKT) FROM LuotThue',DBSETUP(DB))),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) BETWEEN 3 AND 5 gồm cả 3 và 5. (b) WHERE x = NULL tìm giá trị rỗng. (c) COUNT(*) bỏ qua dòng có NULL. (d) ORDER BY mặc định tăng dần. (e) LIMIT đặt trước WHERE.','',P('(a) <b>Đúng</b>.','(b) <b>Sai</b>: dùng <b>IS NULL</b>.','(c) <b>Sai</b>: COUNT(*) đếm mọi dòng.','(d) <b>Đúng</b>.','(e) <b>Sai</b>: LIMIT viết sau cùng.'),20))
S+=END(c,B,['<b>SELECT … FROM … WHERE … ORDER BY … LIMIT</b>.','<b>DISTINCT</b> loại trùng; <b>IN, BETWEEN, LIKE, IS NULL</b> cho điều kiện.','Trộn AND và OR: <b>đặt ngoặc</b>.','Hàm tổng hợp bỏ qua NULL; <b>COUNT(DISTINCT)</b> đếm khác nhau.','“Từ … trở lên” là <b>&gt;=</b>.'],[('Khác nhau','COUNT(DISTINCT)'),('Sắp giảm','ORDER BY … DESC'),('Khớp mẫu','LIKE \'%…\''),('Rỗng','IS NULL')],'Thiếu ngoặc khi trộn AND/OR; dùng = NULL; nhầm &gt; với &gt;=; đếm trùng.',['<b>SELECT * </b> chỉ nên dùng khi học.','<b>Chuỗi</b> trong nháy đơn.','Ngày dạng chữ so sánh được theo thứ tự chữ.'],['<b>CASE WHEN</b>.','<b>COALESCE</b>.','Tối ưu bằng chỉ mục.'],
 [('Mệnh đề lọc dòng?',),('Sắp giảm dần?',),('Đếm giá trị khác nhau?',),('Điều kiện rỗng?',),('Điều kiện “từ 5 trở lên”?',)],
 [('<b>WHERE</b>.',),('<b>ORDER BY … DESC</b>.',),('<b>COUNT(DISTINCT cột)</b>.',),('<b>IS NULL</b>.',),('<b>&gt;= 5</b>.',)],
 [('Mức 1. Liệt kê tên khách có tên bắt đầu bằng K.',),('Mức 1. Đếm số lượt thuê tại trạm DN01.',),('Mức 2. Điểm cao nhất, thấp nhất, trung bình số giờ thuê.',),('Mức 2. Liệt kê các lượt thuê năm 2026 tại DN01 hoặc DN02 có số giờ từ 3 trở lên, xếp giảm dần.',),('Mức 3 (HSG). Tổng số giờ thuê của tất cả các lượt thuê xe điện.',),('Mức 3 (HSG). Có bao nhiêu khách khác nhau đã từng thuê xe đạp?',)],
 [(SQL1("SELECT TenKT FROM KhachThue WHERE TenKT LIKE 'K%'",DBSETUP(DB))+'.',),(SQL1("SELECT COUNT(*) FROM LuotThue WHERE Tram='DN01'",DBSETUP(DB))+'.',),('<code>MAX, MIN, AVG(SoGio)</code> = %s.'%SQL1('SELECT MAX(SoGio), MIN(SoGio), ROUND(AVG(SoGio),2) FROM LuotThue',DBSETUP(DB)),),('Có ngoặc quanh OR; ORDER BY SoGio DESC.',),('JOIN PhuongTien, SUM(SoGio): <b>%s</b>.'%SQL1("SELECT SUM(l.SoGio) FROM LuotThue l JOIN PhuongTien p ON l.MaPT=p.MaPT WHERE p.LoaiPT='Xe điện'",DBSETUP(DB)),),('COUNT(DISTINCT MaKT) với JOIN: <b>%s</b>.'%SQL1("SELECT COUNT(DISTINCT l.MaKT) FROM LuotThue l JOIN PhuongTien p ON l.MaPT=p.MaPT WHERE p.LoaiPT='Xe đạp'",DBSETUP(DB)),)],hper=2)
mkdeck('c3a.html','SQL 3A · Truy vấn và hàm tổng hợp',S)
